// Makes the background music from the catalog (src/common/music/musicTracks.ts):
// downloads each original, converts it to assets/music/<id>.mp3 (same loudness for all, 112 kbit/s)
// and measures the waveform the players draw (src/common/music/musicWaveforms.ts, generated – do not edit).
// Needs ffmpeg. Existing mp3 files are kept; delete one to make it anew.
//   npx tsx scripts/make-music.ts
import {execFileSync} from 'child_process';
import {existsSync, mkdtempSync, rmSync, writeFileSync} from 'fs';
import {tmpdir} from 'os';
import * as path from 'path';
import {MUSIC_TRACKS, musicFile} from '../src/common/music/musicTracks';

// Bars of the drawn waveform: enough detail for a wide admin row, still small in the bundle
const BARS = 120;
// Mono samples per second for the measurement: plenty for peaks, small in memory
const MEASURE_RATE = 4000;

// curl instead of fetch: some hosts (incompetech) time out for Node's fetch but answer curl
function download(url: string, target: string): void {
  execFileSync('curl', ['-sSfL', '--retry', '3', '-A', 'Mozilla/5.0', '-o', target, url]);
}

function convert(source: string, target: string): void {
  // loudnorm: the tracks come from different authors and are very differently loud
  execFileSync('ffmpeg', ['-v', 'error', '-y', '-i', source, '-vn', '-ac', '2', '-ar', '44100',
    '-af', 'loudnorm=I=-18:TP=-1.5:LRA=11', '-c:a', 'libmp3lame', '-b:a', '112k', target]);
}

function measure(file: string): {duration: number, peaks: Array<number>} {
  const pcm = execFileSync('ffmpeg', ['-v', 'error', '-i', file, '-ac', '1', '-ar', String(MEASURE_RATE), '-f', 's16le', '-'],
    {maxBuffer: 1024 * 1024 * 512});
  const samples = new Int16Array(pcm.buffer, pcm.byteOffset, Math.floor(pcm.length / 2));
  const perBar = Math.max(1, Math.floor(samples.length / BARS));
  const raw: Array<number> = [];
  for (let bar = 0; bar < BARS; bar++) {
    // RMS instead of the peak: quiet passages stay visibly lower than loud ones
    let sum = 0;
    const start = bar * perBar;
    const end = Math.min(samples.length, start + perBar);
    for (let index = start; index < end; index++) {
      sum += samples[index] * samples[index];
    }
    raw.push(Math.sqrt(sum / Math.max(1, end - start)));
  }
  const loudest = Math.max(...raw, 1);
  return {
    duration: Math.round(samples.length / MEASURE_RATE),
    peaks: raw.map((value) => Math.round((value / loudest) * 100) / 100),
  };
}

async function main(): Promise<void> {
  const work = mkdtempSync(path.join(tmpdir(), 'tm-music-'));
  const waveforms: Record<string, {duration: number, peaks: Array<number>}> = {};
  try {
    for (const track of MUSIC_TRACKS) {
      const target = musicFile(track.id);
      if (!existsSync(target)) {
        const original = path.join(work, track.id + path.extname(new URL(track.download).pathname));
        download(track.download, original);
        convert(original, target);
        console.log('made', target);
      }
      waveforms[track.id] = measure(target);
    }
  } finally {
    rmSync(work, {recursive: true, force: true});
  }
  const body = Object.entries(waveforms)
    .map(([id, {duration, peaks}]) => `  '${id}': {duration: ${duration}, peaks: [${peaks.join(', ')}]},`)
    .join('\n');
  writeFileSync('src/common/music/musicWaveforms.ts',
    '// Generated by scripts/make-music.ts – do not edit. Length in seconds and loudness (0..1) per bar of each track.\n' +
    'export type MusicWaveform = {duration: number, peaks: ReadonlyArray<number>};\n\n' +
    `export const MUSIC_WAVEFORMS: Readonly<Record<string, MusicWaveform>> = {\n${body}\n};\n`);
  console.log('wrote src/common/music/musicWaveforms.ts');
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
